const StudentListItem: React.FC<{
    student: Student;
    onSelect: (student: Student) => void;
    bulkMode: boolean;
    isSelected: boolean;
    onToggleSelect: (studentId: string) => void;
    view: 'boarding' | 'alighting' | 'checkin' | 'checkout';
    onUpdateStatus: (student: Student, newStatus: StudentStatus) => void;
    isQuickScanMode?: boolean;
}> = ({ student, onSelect, bulkMode, isSelected, onToggleSelect, view, onUpdateStatus, isQuickScanMode }) => {
    const isQuickScanTarget = 
        (view === 'boarding' && student.status === StudentStatus.NotBoarded) ||
        (view === 'alighting' && student.status === StudentStatus.Boarded) ||
        (view === 'checkin' && student.status === StudentStatus.NotArrived) ||
        (view === 'checkout' && student.status === StudentStatus.InSchool);

    const getQuickScanStatus = () => {
        if (view === 'boarding') return StudentStatus.Boarded;
        if (view === 'alighting') return StudentStatus.Alighted;
        if (view === 'checkin') return StudentStatus.InSchool;
        if (view === 'checkout') return StudentStatus.LeftSchool;
        return StudentStatus.Boarded;
    };

    return (
        <li 
            className={`bg-white p-4 border-b border-gray-50 flex items-start gap-4 transition-colors ${isQuickScanMode && isQuickScanTarget ? 'cursor-pointer hover:bg-blue-50' : ''}`}
            onClick={isQuickScanMode && isQuickScanTarget ? () => onUpdateStatus(student, getQuickScanStatus()) : () => onSelect(student)}
        >
            {bulkMode ? (
                <div onClick={e => e.stopPropagation()} className="flex items-center h-full pt-3">
                    <input type="checkbox" checked={isSelected} onChange={() => onToggleSelect(student.id)} className="w-6 h-6 rounded text-[#E70D8D] border-gray-300 focus:ring-[#E70D8D]" />
                </div>
            ) : (
                <div className="relative">
                    <img src={student.imgUrl} alt={student.name} className="w-12 h-12 rounded-full object-cover border border-gray-100"/>
                    {student.status === StudentStatus.Boarded && <div className="absolute -bottom-1 -right-1 bg-green-500 rounded-full p-0.5 border-2 border-white"><Icon name="checkCircle" className="w-3 h-3 text-white"/></div>}
                </div>
            )}
            <div className="flex-grow cursor-pointer" onClick={() => onSelect(student)}>
                <p className="font-bold text-gray-800 text-base">{student.name}</p>
                <p className="text-xs text-gray-500 font-medium">ID: {student.admissionNumber} &bull; {student.grade}</p>
                <div className="mt-2"><StatusBadge status={student.status} /></div>
                {student.alert && <StudentAlert alertText={student.alert} />}
            </div>
            {!bulkMode && !isQuickScanMode && (
                <div className="flex flex-col gap-2 flex-shrink-0">
                    {view === 'boarding' && student.status === StudentStatus.NotBoarded && (
                        <>
                            <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.Boarded); }} className="px-3 py-1.5 text-xs bg-[#303690] text-white rounded-lg font-bold hover:opacity-90 transition-colors shadow-sm">Board</button>
                            <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.Absent); }} className="px-3 py-1.5 text-xs bg-red-100 text-red-700 rounded-lg font-bold hover:bg-red-200 transition-colors">Absent</button>
                        </>
                    )}
                    {view === 'alighting' && student.status === StudentStatus.Boarded && (
                        <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.Alighted); }} className="px-3 py-1.5 text-xs bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 transition-colors shadow-sm">Alight</button>
                    )}
                    {view === 'checkin' && student.status === StudentStatus.NotArrived && (
                        <>
                            <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.InSchool); }} className="px-3 py-1.5 text-xs bg-[#303690] text-white rounded-lg font-bold hover:opacity-90 transition-colors shadow-sm">Check In</button>
                            <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.Absent); }} className="px-3 py-1.5 text-xs bg-red-100 text-red-700 rounded-lg font-bold hover:bg-red-200 transition-colors">Absent</button>
                        </>
                    )}
                    {view === 'checkout' && student.status === StudentStatus.InSchool && (
                        <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.LeftSchool); }} className="px-3 py-1.5 text-xs bg-[#303690] text-white rounded-lg font-bold hover:opacity-90 transition-colors shadow-sm">Check Out</button>
                    )}
                </div>
            )}
        </li>
    );
};

const GpsStatusIndicator: React.FC<{ status: GpsStatus; onClick: () => void; }> = ({ status, onClick }) => {
    const config: Record<GpsStatus, { text: string; color: string; bg: string }> = {
        active: { text: 'GPS Active', color: 'text-green-600', bg: 'bg-green-100' },
        inactive: { text: 'GPS Inactive', color: 'text-gray-500', bg: 'bg-gray-100' },
        error: { text: 'GPS Error', color: 'text-red-600', bg: 'bg-red-100' },
    };
    return (
        <button onClick={onClick} className={`flex items-center gap-1.5 text-[10px] uppercase tracking-wider ${config[status].color} ${config[status].bg} rounded-full px-2 py-1 hover:opacity-80 transition-opacity`}>
            <Icon name="crosshair" className="w-3 h-3" />
            <span className="font-bold">{config[status].text}</span>
        </button>
    );
};

const ModeToggle: React.FC<{
    id: string;
    label: string;
    icon: IconName;
    checked: boolean;
    onChange: (checked: boolean) => void;
}> = ({ id, label, icon, checked, onChange }) => (
    <div className="flex items-center">
        <div className={`p-1.5 rounded-full mr-1.5 ${checked ? 'bg-pink-100 text-[#E70D8D]' : 'bg-gray-100 text-gray-500'}`}>
             <Icon name={icon} className="w-3 h-3" />
        </div>
        <label htmlFor={id} className={`text-xs font-bold uppercase tracking-wide ${checked ? 'text-[#E70D8D]' : 'text-gray-500'} mr-2`}>{label}</label>
        <div className="relative inline-block w-9 align-middle select-none transition duration-200 ease-in">
            <input 
                type="checkbox" 
                name={id} 
                id={id} 
                checked={checked} 
                onChange={(e) => onChange(e.target.checked)} 
                className="toggle-checkbox absolute block w-5 h-5 rounded-full bg-white border-2 appearance-none cursor-pointer top-0.5 left-0.5"
            />
            <label htmlFor={id} className={`toggle-label block overflow-hidden h-6 rounded-full cursor-pointer ${checked ? 'bg-[#E70D8D]' : 'bg-gray-300'}`}></label>
        </div>
    </div>
);

const ActiveTripScreen: React.FC<{
    trip: Trip;
    onEndTrip: () => void;
    onUpdateStudent: (studentId: string, newStatus: StudentStatus) => void;
    onReportIssue: () => void;
    showToast: (message: string, type?: ToastType) => void;
    gpsStatus: GpsStatus;
    onGpsClick: () => void;
    setActiveTrip: React.Dispatch<React.SetStateAction<Trip | null>>;
}> = ({ trip, onEndTrip, onUpdateStudent, onReportIssue, showToast, gpsStatus, onGpsClick, setActiveTrip }) => {
    const [view, setView] = useState<'boarding' | 'alighting'>(trip.type === 'Morning' ? 'boarding' : 'alighting');
    const [searchTerm, setSearchTerm] = useState('');
    const [manualMode, setManualMode] = useState(false);
    const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);
    const [isScanning, setIsScanning] = useState(false);
    const [scannedStudent, setScannedStudent] = useState<{student: Student, status: StudentStatus} | null>(null);
    const [studentToConfirm, setStudentToConfirm] = useState<Student | null>(null);
    const [isQuickScanModeActive, setIsQuickScanModeActive] = useState(false);
    const [isEndingTrip, setIsEndingTrip] = useState(false);
    const [isEndConfirmationOpen, setIsEndConfirmationOpen] = useState(false);
    const selectAllCheckboxRef = useRef<HTMLInputElement>(null);
    const scanIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const [activeStudent, setActiveStudent] = useState<Student | null>(null);

    const studentsToShow = useMemo(() => {
        let list = trip.students;
        if (view === 'boarding') {
            list = trip.students.filter(s => [StudentStatus.NotBoarded, StudentStatus.Absent].includes(s.status));
        } else {
            list = trip.students.filter(s => [StudentStatus.Boarded, StudentStatus.Alighted].includes(s.status));
        }

        if (!searchTerm) return list;

        return list.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.admissionNumber.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [view, trip.students, searchTerm]);

    useEffect(() => {
        setSelectedStudentIds([]); 
    }, [manualMode, view]);

    useEffect(() => {
        setIsQuickScanModeActive(false);
    }, [view]);

    useEffect(() => {
        const stopScanning = () => {
            if (scanIntervalRef.current) {
                clearInterval(scanIntervalRef.current);
                scanIntervalRef.current = null;
            }
        };

        if (isQuickScanModeActive && (view === 'boarding' || view === 'alighting')) {
            scanIntervalRef.current = setInterval(() => {
                setActiveTrip(currentTrip => {
                    if (!currentTrip) {
                        stopScanning();
                        return null;
                    }

                    const targetStatus = view === 'boarding' ? StudentStatus.NotBoarded : StudentStatus.Boarded;
                    const newStatus = view === 'boarding' ? StudentStatus.Boarded : StudentStatus.Alighted;

                    const studentToProcess = currentTrip.students.find(s => s.status === targetStatus);

                    if (studentToProcess) {
                        showToast(`${studentToProcess.name} ${view === 'boarding' ? 'boarded' : 'alighted'}.`, 'success');
                        return {
                            ...currentTrip,
                            students: currentTrip.students.map(s => s.id === studentToProcess.id ? { ...s, status: newStatus, lastUpdateTime: new Date() } : s)
                        };
                    } else {
                        stopScanning();
                        setIsQuickScanModeActive(false);
                        showToast(`All students ${view === 'boarding' ? 'boarded' : 'alighted'} via Quick Scan.`, 'info');
                        return currentTrip;
                    }
                });
            }, 2000);
        }

        return () => stopScanning();
    }, [isQuickScanModeActive, view, setActiveTrip, showToast]);


    useEffect(() => {
        if (selectAllCheckboxRef.current) {
            const allVisibleSelected = studentsToShow.length > 0 && selectedStudentIds.length === studentsToShow.length;
            const someSelected = selectedStudentIds.length > 0 && selectedStudentIds.length < studentsToShow.length;
            selectAllCheckboxRef.current.checked = allVisibleSelected;
            selectAllCheckboxRef.current.indeterminate = someSelected;
        }
    }, [selectedStudentIds, studentsToShow]);

    const handleEndTrip = () => {
        setIsEndConfirmationOpen(false);
        const studentsOnBoard = trip.students.filter(s => s.status === StudentStatus.Boarded);
        if (studentsOnBoard.length > 0) {
            showToast(`Cannot end trip. ${studentsOnBoard.length} student(s) still on board.`, 'error');
        } else {
            setIsEndingTrip(true);
            setTimeout(() => {
                onEndTrip();
            }, 1500);
        }
    };

    const proceedWithBoarding = (student: Student) => {
        if (isQuickScanModeActive) {
            onUpdateStudent(student.id, StudentStatus.Boarded);
            showToast(`${student.name} boarded.`, 'success');
            return;
        }

        setIsScanning(true);
        setTimeout(() => {
            setIsScanning(false);
            onUpdateStudent(student.id, StudentStatus.Boarded);
            setScannedStudent({ student, status: StudentStatus.Boarded });
            setTimeout(() => setScannedStudent(null), 2000);
        }, 1500);
    };

    const proceedWithAlighting = (student: Student) => {
        if (isQuickScanModeActive) {
            onUpdateStudent(student.id, StudentStatus.Alighted);
            showToast(`${student.name} alighted.`, 'success');
            return;
        }

        setIsScanning(true);
        setTimeout(() => {
            setIsScanning(false);
            onUpdateStudent(student.id, StudentStatus.Alighted);
            setScannedStudent({ student, status: StudentStatus.Alighted });
            setTimeout(() => setScannedStudent(null), 2000);
        }, 1500);
    };

    const handleStudentAction = (student: Student, newStatus: StudentStatus) => {
        if (newStatus === StudentStatus.Boarded) {
            if (student.alert) {
                setStudentToConfirm(student);
                return;
            }
            proceedWithBoarding(student);
        } else if (newStatus === StudentStatus.Alighted) {
            if (manualMode) {
                onUpdateStudent(student.id, newStatus);
                showToast(`${student.name} marked as alighted.`, 'info');
            } else {
                proceedWithAlighting(student);
            }
        } else if (newStatus === StudentStatus.Absent) {
            onUpdateStudent(student.id, newStatus);
            showToast(`${student.name} marked as absent.`, 'info');
        } else {
             // Generic update (e.g. reversals)
             onUpdateStudent(student.id, newStatus);
             showToast(`${student.name} status updated to ${newStatus}.`, 'info');
        }
    };

    const handleToggleSelect = (studentId: string) => {
        setSelectedStudentIds(prev => prev.includes(studentId) ? prev.filter(id => id !== studentId) : [...prev, studentId]);
    };

    const handleBulkUpdate = (status: StudentStatus) => {
        selectedStudentIds.forEach(id => onUpdateStudent(id, status));
        setSelectedStudentIds([]);
    };

    const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.checked) {
            setSelectedStudentIds(studentsToShow.map(s => s.id));
        } else {
            setSelectedStudentIds([]);
        }
    };

    return (
        <div className="flex flex-col h-full">
            <Header title={`${trip.type} Trip`} />
            <div className="bg-white px-4 py-3 border-b border-gray-100">
                <div className="flex justify-between items-center text-sm text-gray-600 mb-2">
                    <div className="flex items-center gap-2">
                        <span className="font-bold text-[#303690]">{MOCK_DRIVER.assignedZone}</span>
                        <span className="text-gray-300">|</span>
                        <span className="text-xs">{trip.startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                    </div>
                    <GpsStatusIndicator status={gpsStatus} onClick={onGpsClick} />
                </div>

                {/* Route Information Section */}
                <div className="bg-blue-50/50 border border-blue-100/50 rounded-xl p-3 mb-3 flex items-center gap-3">
                    <div className="bg-white p-2 rounded-lg text-[#303690] shadow-sm">
                        <Icon name="map" className="w-5 h-5"/>
                    </div>
                    <div className="flex-grow">
                        <p className="text-[10px] font-bold text-gray-400 uppercase leading-none mb-1">Current Route</p>
                        <p className="font-bold text-gray-800 text-sm">{trip.route.name}</p>
                    </div>
                    <div className="text-right">
                         <p className="text-[10px] font-bold text-gray-400 uppercase leading-none mb-1">Zone</p>
                         <p className="font-bold text-gray-700 text-xs">{trip.route.zone}</p>
                    </div>
                </div>

                <div className="flex items-center justify-between">
                    <div className="text-xs font-bold text-gray-500 uppercase">Progress</div>
                    <div className="flex items-center gap-1">
                        <span className="font-bold text-2xl text-[#E70D8D]">{trip.students.filter(s => s.status === StudentStatus.Boarded).length}</span>
                        <span className="text-gray-400 text-sm">/ {trip.students.length}</span>
                    </div>
                </div>
                <div className="w-full bg-gray-100 rounded-full h-1.5 mt-1">
                    <div 
                        className="bg-[#E70D8D] h-1.5 rounded-full transition-all duration-500" 
                        style={{ width: `${(trip.students.filter(s => s.status === StudentStatus.Boarded).length / trip.students.length) * 100}%` }}
                    ></div>
                </div>
            </div>
            <div className="flex bg-white border-b border-gray-100">
                <button className={`flex-1 p-3 font-semibold text-sm transition-colors relative ${view === 'boarding' ? 'text-[#E70D8D]' : 'text-gray-500'}`} onClick={() => setView('boarding')}>
                    Boarding
                    {view === 'boarding' && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-[#E70D8D]"></div>}
                </button>
                <button className={`flex-1 p-3 font-semibold text-sm transition-colors relative ${view === 'alighting' ? 'text-[#E70D8D]' : 'text-gray-500'}`} onClick={() => setView('alighting')}>
                    Alighting
                    {view === 'alighting' && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-[#E70D8D]"></div>}
                </button>
            </div>
            <div className="p-4 bg-white border-b border-gray-50 sticky top-[230px] z-10">
                <div className="relative">
                    <Icon name="search" className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5"/>
                    <input type="text" placeholder="Search students..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-gray-50 rounded-xl p-3 pl-10 focus:outline-none focus:ring-2 focus:ring-pink-100 text-sm" />
                </div>
                <div className="flex items-center justify-between mt-3">
                    <div>
                        {manualMode && (
                            <div className="flex items-center gap-2">
                                <input 
                                    type="checkbox" 
                                    id="select-all" 
                                    ref={selectAllCheckboxRef}
                                    onChange={handleSelectAll}
                                    className="w-5 h-5 rounded text-[#E70D8D] border-gray-300 focus:ring-[#E70D8D]" 
                                />
                                <label htmlFor="select-all" className="text-xs font-bold uppercase text-gray-500 select-none">Select All</label>
                            </div>
                        )}
                    </div>
                    <div className="flex items-center gap-4">
                        <ModeToggle 
                            id="quick-scan-mode"
                            label="Quick Scan"
                            icon="zap"
                            checked={isQuickScanModeActive}
                            onChange={(checked) => {
                                setIsQuickScanModeActive(checked);
                                if(checked) setManualMode(false);
                            }}
                        />
                        <ModeToggle 
                            id="manual-mode"
                            label="Manual"
                            icon="userCheck"
                            checked={manualMode}
                            onChange={(checked) => {
                                setManualMode(checked);
                                if(checked) setIsQuickScanModeActive(false);
                            }}
                        />
                    </div>
                </div>
            </div>
            <div className="flex-grow overflow-y-auto pb-36 bg-white">
                {isQuickScanModeActive && <NfcScanningOverlay activeText="Quick Scan Active" />}
                {studentsToShow.length > 0 ? (
                    <ul>{studentsToShow.map(s => <StudentListItem key={s.id} student={s} onSelect={setActiveStudent} bulkMode={manualMode} isSelected={selectedStudentIds.includes(s.id)} onToggleSelect={handleToggleSelect} view={view} onUpdateStatus={handleStudentAction} isQuickScanMode={isQuickScanModeActive && (view === 'boarding' || view === 'alighting')}/>)}</ul>
                ) : (
                    <div className="text-center p-8 text-gray-400 mt-8">
                        <div className="bg-gray-50 rounded-full w-24 h-24 flex items-center justify-center mx-auto mb-4">
                             <Icon name={view === 'boarding' ? 'checkCircle' : 'bus'} className="w-10 h-10 text-gray-300"/>
                        </div>
                        <p className="font-semibold">{view === 'boarding' ? 'All students boarded!' : 'No students to alight.'}</p>
                    </div>
                )}
            </div>
            {manualMode && selectedStudentIds.length > 0 && (
                <div className="absolute bottom-24 left-4 right-4 bg-[#303690] text-white p-4 rounded-2xl shadow-xl flex justify-between items-center z-20">
                    <p className="font-bold">{selectedStudentIds.length} selected</p>
                    <div className="flex gap-2">
                         {view === 'boarding' && <>
                            <button onClick={() => handleBulkUpdate(StudentStatus.Boarded)} className="bg-[#E70D8D] text-white font-bold px-4 py-2 rounded-xl text-sm">Board</button>
                            <button onClick={() => handleBulkUpdate(StudentStatus.Absent)} className="bg-white/20 text-white font-bold px-4 py-2 rounded-xl text-sm">Absent</button>
                         </>}
                         {view === 'alighting' && <button onClick={() => handleBulkUpdate(StudentStatus.Alighted)} className="bg-[#E70D8D] text-white font-bold px-4 py-2 rounded-xl text-sm">Alight</button>}
                    </div>
                </div>
            )}
            <div className={`absolute bottom-0 left-0 right-0 bg-white p-4 border-t border-gray-100 shadow-2xl ${view === 'alighting' ? 'grid grid-cols-4 gap-4' : 'flex items-center'}`}>
                <button onClick={onReportIssue} className={`bg-yellow-100 text-yellow-700 font-bold p-3 rounded-xl flex flex-col items-center justify-center gap-1 h-14 transition-all duration-300 ${view === 'alighting' ? 'col-span-1' : 'w-full'}`}>
                    <Icon name="alertTriangle" className="w-5 h-5" />
                    <span className="text-[10px] uppercase">Report</span>
                </button>
                {view === 'alighting' && (
                    <button onClick={() => setIsEndConfirmationOpen(true)} disabled={isEndingTrip} className="bg-[#E70D8D] text-white font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 col-span-3 h-14 shadow-lg shadow-pink-200 animate-slide-up-button">
                        {isEndingTrip ? <Spinner className="text-white"/> : <><Icon name="logOut" className="w-5 h-5"/>End Trip</>}
                    </button>
                )}
            </div>
            {isScanning && <NfcScanningOverlay />}
            {scannedStudent && <NfcSuccessModal student={scannedStudent.student} status={scannedStudent.status} />}
             <BoardingConfirmationModal
                isOpen={!!studentToConfirm}
                onClose={() => setStudentToConfirm(null)}
                student={studentToConfirm}
                onConfirm={(student) => {
                    setStudentToConfirm(null);
                    proceedWithBoarding(student);
                }}
            />
             <StudentActionModal
                isOpen={!!activeStudent}
                onClose={() => setActiveStudent(null)}
                student={activeStudent}
                onUpdateStatus={handleStudentAction}
                onNotify={(name) => showToast(`Notifying ${name}'s guardian.`, 'info')}
                onCall={(name) => showToast(`Calling ${name}'s guardian.`, 'info')}
                mode="trip"
            />
            <Modal isOpen={isEndConfirmationOpen} onClose={() => setIsEndConfirmationOpen(false)} title="End Trip?">
                <div className="flex flex-col items-center pb-2 text-center">
                    <div className="w-20 h-20 bg-pink-50 rounded-full flex items-center justify-center mb-6">
                        <Icon name="logOut" className="w-8 h-8 text-[#E70D8D]" />
                    </div>
                    <h3 className="text-xl font-bold text-gray-900 mb-2">Are you sure you want to end this trip?</h3>
                    <p className="text-gray-500 text-sm mb-8 px-4">
                        Please ensure all students have alighted or have been accounted for before ending the trip.
                    </p>
                    <div className="grid grid-cols-2 gap-4 w-full">
                        <button onClick={() => setIsEndConfirmationOpen(false)} className="py-4 rounded-2xl bg-gray-50 text-gray-600 font-bold text-sm uppercase tracking-wide">
                            Cancel
                        </button>
                        <button onClick={handleEndTrip} className="py-4 rounded-2xl bg-[#E70D8D] text-white font-bold shadow-lg shadow-pink-200 text-sm uppercase tracking-wide">
                            Confirm
                        </button>
                    </div>
                </div>
            </Modal>
            <style>{`
                .toggle-checkbox:checked { right: 0; border-color: #E70D8D; } 
                .toggle-checkbox:checked + .toggle-label { background-color: #E70D8D; } 
                .toggle-label { transition: background-color 0.2s ease-in-out; }
                @keyframes slide-up-button {
                    from { transform: translateY(100%); opacity: 0; }
                    to { transform: translateY(0); opacity: 1; }
                }
                .animate-slide-up-button { animation: slide-up-button 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
            `}</style>
        </div>
    );
};

const NfcScanningOverlay: React.FC<{ activeText?: string }> = ({ activeText }) => (
    <div className={`absolute inset-0 bg-[#303690] z-40 flex flex-col justify-center items-center text-white backdrop-blur-sm ${activeText ? 'bg-opacity-90' : 'bg-opacity-90'}`}>
        <div className="relative flex items-center justify-center">
            {!activeText && <div className="absolute w-32 h-32 bg-[#E70D8D] rounded-full animate-ping opacity-50"></div>}
            <div className="bg-white/10 p-8 rounded-full backdrop-blur-md">
                <Icon name={activeText ? 'zap' : 'smartphone'} className="w-16 h-16 text-pink-400" />
            </div>
        </div>
        <p className="mt-8 text-xl font-bold tracking-wider text-white">{activeText || 'Ready to Scan...'}</p>
        <p className="text-blue-300 mt-2">Hold card near back of device</p>
    </div>
);

const NfcSuccessModal: React.FC<{ student: Student; status: StudentStatus }> = ({ student, status }) => (
    <div className="absolute inset-0 z-50 flex justify-center items-end p-4 pointer-events-none">
        <div className="bg-white rounded-2xl shadow-2xl flex items-center p-4 gap-4 w-full max-w-sm animate-slide-up-fade-out border border-gray-100">
            <div className="relative flex-shrink-0">
                <img src={student.imgUrl} alt={student.name} className="w-16 h-16 rounded-full object-cover" />
                <div className={`absolute -bottom-1 -right-1 rounded-full p-1 border-2 border-white ${status === StudentStatus.Boarded || status === StudentStatus.InSchool ? 'bg-green-500' : 'bg-[#303690]'}`}>
                    <Icon name={status === StudentStatus.Boarded || status === StudentStatus.InSchool ? 'checkCircle' : 'logOut'} className="w-5 h-5 text-white" />
                </div>
            </div>
            <div className="flex-grow">
                <p className="font-bold text-lg text-gray-800">{student.name}</p>
                <p className={`text-sm font-bold uppercase tracking-wide ${status === StudentStatus.Boarded || status === StudentStatus.InSchool ? 'text-green-600' : 'text-[#303690]'}`}>{status} Successfully</p>
            </div>
        </div>
        <style>{`
            @keyframes slide-up-fade-out {
              0% { opacity: 0; transform: translateY(100%); }
              15% { opacity: 1; transform: translateY(0); }
              85% { opacity: 1; transform: translateY(0); }
              100% { opacity: 0; transform: translateY(100%); }
            }
            .animate-slide-up-fade-out { animation: slide-up-fade-out 2s ease-in-out forwards; }
        `}</style>
    </div>
);

const BoardingConfirmationModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    student: Student | null;
    onConfirm: (student: Student) => void;
    title?: string;
    confirmText?: string;
}> = ({ isOpen, onClose, student, onConfirm, title = "Confirmation", confirmText = "Confirm" }) => {
    if (!student) return null;
    return (
        <Modal isOpen={isOpen} onClose={onClose} title={title}>
            <div className="flex flex-col items-center pb-2">
                 <div className="relative mb-6 mt-2">
                    <div className="absolute inset-0 bg-pink-200 rounded-full blur-lg opacity-50 animate-pulse"></div>
                    <img src={student.imgUrl} alt={student.name} className="w-24 h-24 rounded-full border-4 border-white shadow-xl relative z-10 object-cover" />
                    {student.alert && (
                        <div className="absolute -bottom-2 -right-2 bg-[#E70D8D] rounded-full p-2.5 border-4 border-white z-20 shadow-sm">
                            <Icon name="alertTriangle" className="w-5 h-5 text-white" />
                        </div>
                    )}
                 </div>

                 <h3 className="text-2xl font-bold text-gray-900 mb-1">{student.name}</h3>
                 <p className="text-gray-500 font-medium text-sm mb-6">{student.grade} • {student.admissionNumber}</p>

                 {student.alert && (
                     <div className="w-full bg-pink-50 rounded-2xl p-4 mb-8 border border-pink-100 relative overflow-hidden">
                        <div className="absolute top-0 left-0 w-1 h-full bg-[#E70D8D]"></div>
                        <div className="flex flex-col items-center relative z-10">
                            <p className="text-[#E70D8D] font-bold text-xs uppercase tracking-widest mb-1">Alert</p>
                            <p className="text-gray-800 text-center font-semibold">{student.alert}</p>
                        </div>
                     </div>
                 )}

                 {!student.alert && (
                     <p className="text-gray-600 text-center mb-8 px-4">
                        Please confirm the action for this student.
                     </p>
                 )}

                 <div className="grid grid-cols-2 gap-4 w-full">
                    <button onClick={onClose} className="py-4 rounded-2xl bg-gray-50 text-gray-600 font-bold hover:bg-gray-100 transition-colors text-sm uppercase tracking-wide">
                        Cancel
                    </button>
                    <button onClick={() => onConfirm(student)} className="py-4 rounded-2xl bg-[#E70D8D] text-white font-bold shadow-lg shadow-pink-200 hover:shadow-xl hover:opacity-95 transition-all transform active:scale-[0.98] text-sm uppercase tracking-wide">
                        {confirmText}
                    </button>
                 </div>
            </div>
        </Modal>
    );
};


const TripSummaryScreen: React.FC<{ trip: Trip; onDone: () => void; onBack: () => void; }> = ({ trip, onDone, onBack }) => {
    const [isSubmitting, setIsSubmitting] = useState(false);
    const boardedCount = trip.students.filter(s => s.status === StudentStatus.Alighted || s.status === StudentStatus.Boarded).length;
    const alightedCount = trip.students.filter(s => s.status === StudentStatus.Alighted).length;
    const absentCount = trip.students.filter(s => s.status === StudentStatus.Absent).length;
    const duration = trip.endTime ? Math.round((trip.endTime.getTime() - trip.startTime.getTime()) / 60000) : 0;

    const handleSubmit = () => {
        setIsSubmitting(true);
        setTimeout(() => {
            onDone();
        }, 1500);
    };

    return (
        <div className="flex flex-col h-full bg-gray-50">
            <Header title="Trip Summary"/>
            <div className="flex-grow p-6 overflow-y-auto">
                <div className="bg-[#E70D8D] rounded-2xl shadow-lg p-6 mb-6 text-center text-white relative overflow-hidden">
                     <div className="absolute -top-10 -right-10 w-32 h-32 bg-white rounded-full blur-2xl opacity-20"></div>
                     <div className="relative z-10">
                        <h2 className="text-2xl font-bold mb-1">{trip.type} Trip Completed</h2>
                        <p className="text-pink-100">{trip.route.name}</p>
                     </div>
                </div>
                <div className="grid grid-cols-2 gap-4 mb-6">
                    <SummaryCard icon="clock" label="Duration" value={`${duration} min`} />
                    <SummaryCard icon="users" label="Boarded" value={`${boardedCount}`} />
                    <SummaryCard icon="logOut" label="Alighted" value={`${alightedCount}`} />
                    <SummaryCard icon="xCircle" label="Absent" value={`${absentCount}`} />
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase text-gray-500 mb-3 tracking-wider">Issues Reported ({trip.issues.length})</h3>
                    {trip.issues.length > 0 ? (
                        <ul className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 space-y-3">{trip.issues.map((issue, index) => (<li key={index} className="border-b border-gray-100 last:border-b-0 pb-2 last:pb-0"><p className="font-semibold text-gray-800">{issue.type}</p><p className="text-sm text-gray-600">{issue.note}</p></li>))}</ul>
                    ) : (
                        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 text-center text-gray-400">No issues reported.</div>
                    )}
                </div>
            </div>
            <div className="p-4 bg-white border-t border-gray-100 space-y-3">
                 <button onClick={onBack} className="w-full bg-gray-100 text-gray-600 font-bold py-4 rounded-xl">Go Back</button>
                 <button onClick={handleSubmit} disabled={isSubmitting} className="w-full bg-[#E70D8D] text-white font-bold py-4 rounded-xl shadow-lg hover:opacity-90 transition-colors h-14 flex items-center justify-center">
                    {isSubmitting ? <Spinner className="text-white"/> : 'Submit Report'}
                 </button>
            </div>
        </div>
    );
};

