const ActiveTripScreen: React.FC<{
    trip: Trip;
    onEndTrip: () => void;
    onUpdateStudent: (studentId: string, newStatus: StudentStatus) => void;
    onReportIssue: () => void;
    showToast: (message: string, type?: ToastType) => void;
    gpsStatus: GpsStatus;
    onGpsClick: () => void;
    setActiveTrip: React.Dispatch<React.SetStateAction<Trip | null>>;
    onScanned: (data: {student: Student, status: StudentStatus} | null) => void;
}> = ({ trip, onEndTrip, onUpdateStudent, onReportIssue, showToast, gpsStatus, onGpsClick, setActiveTrip, onScanned }) => {
    const [view, setView] = useState<'boarding' | 'alighting'>(trip.type === 'Morning' ? 'boarding' : 'alighting');
    const [searchTerm, setSearchTerm] = useState('');
    const [manualMode, setManualMode] = useState(false);
    const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);
    const [isScanning, setIsScanning] = useState(false);
    const [studentToConfirm, setStudentToConfirm] = useState<Student | null>(null);
    const [isQuickScanModeActive, setIsQuickScanModeActive] = useState(false);
    const [isEndingTrip, setIsEndingTrip] = useState(false);
    const [isEndConfirmationOpen, setIsEndConfirmationOpen] = useState(false);
    const selectAllCheckboxRef = useRef<HTMLInputElement>(null);
    const scanIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const [activeStudent, setActiveStudent] = useState<Student | null>(null);

    const studentsToShow = useMemo(() => {
        let list = trip.students;
        if (view === 'boarding') {
            list = trip.students.filter(s => [StudentStatus.NotBoarded, StudentStatus.Absent].includes(s.status));
        } else {
            list = trip.students.filter(s => [StudentStatus.Boarded, StudentStatus.Alighted].includes(s.status));
        }

        if (!searchTerm) return list;

        return list.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.admissionNumber.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [view, trip.students, searchTerm]);

    useEffect(() => {
        setSelectedStudentIds([]); 
    }, [manualMode, view]);

    useEffect(() => {
        setIsQuickScanModeActive(false);
    }, [view]);

    useEffect(() => {
        const stopScanning = () => {
            if (scanIntervalRef.current) {
                clearInterval(scanIntervalRef.current);
                scanIntervalRef.current = null;
            }
        };

        if (isQuickScanModeActive && (view === 'boarding' || view === 'alighting')) {
            scanIntervalRef.current = setInterval(() => {
                setActiveTrip(currentTrip => {
                    if (!currentTrip) {
                        stopScanning();
                        return null;
                    }

                    const targetStatus = view === 'boarding' ? StudentStatus.NotBoarded : StudentStatus.Boarded;
                    const newStatus = view === 'boarding' ? StudentStatus.Boarded : StudentStatus.Alighted;

                    const studentToProcess = currentTrip.students.find(s => s.status === targetStatus);

                    if (studentToProcess) {
                        onScanned({ student: studentToProcess, status: newStatus });
                        return {
                            ...currentTrip,
                            students: currentTrip.students.map(s => s.id === studentToProcess.id ? { ...s, status: newStatus, lastUpdateTime: new Date() } : s)
                        };
                    } else {
                        stopScanning();
                        setIsQuickScanModeActive(false);
                        showToast(`All students ${view === 'boarding' ? 'boarded' : 'alighted'} via Quick Scan.`, 'info');
                        return currentTrip;
                    }
                });
            }, 2000);
        }

        return () => stopScanning();
    }, [isQuickScanModeActive, view, setActiveTrip, showToast, onScanned]);


    useEffect(() => {
        if (selectAllCheckboxRef.current) {
            const allVisibleSelected = studentsToShow.length > 0 && selectedStudentIds.length === studentsToShow.length;
            const someSelected = selectedStudentIds.length > 0 && selectedStudentIds.length < studentsToShow.length;
            selectAllCheckboxRef.current.checked = allVisibleSelected;
            selectAllCheckboxRef.current.indeterminate = someSelected;
        }
    }, [selectedStudentIds, studentsToShow]);

    const handleEndTrip = () => {
        setIsEndConfirmationOpen(false);
        const studentsOnBoard = trip.students.filter(s => s.status === StudentStatus.Boarded);
        if (studentsOnBoard.length > 0) {
            showToast(`Cannot end trip. ${studentsOnBoard.length} student(s) still on board.`, 'error');
        } else {
            setIsEndingTrip(true);
            setTimeout(() => {
                onEndTrip();
            }, 1500);
        }
    };

    const proceedWithBoarding = (student: Student) => {
        if (isQuickScanModeActive) {
            onUpdateStudent(student.id, StudentStatus.Boarded);
            onScanned({ student, status: StudentStatus.Boarded });
            return;
        }

        setIsScanning(true);
        setTimeout(() => {
            setIsScanning(false);
            onUpdateStudent(student.id, StudentStatus.Boarded);
            onScanned({ student, status: StudentStatus.Boarded });
        }, 1200);
    };

    const proceedWithAlighting = (student: Student) => {
        if (isQuickScanModeActive) {
            onUpdateStudent(student.id, StudentStatus.Alighted);
            onScanned({ student, status: StudentStatus.Alighted });
            return;
        }

        setIsScanning(true);
        setTimeout(() => {
            setIsScanning(false);
            onUpdateStudent(student.id, StudentStatus.Alighted);
            onScanned({ student, status: StudentStatus.Alighted });
        }, 1200);
    };

    const handleStudentAction = (student: Student, newStatus: StudentStatus) => {
        if (newStatus === StudentStatus.Boarded) {
            if (student.alert) {
                setStudentToConfirm(student);
                return;
            }
            proceedWithBoarding(student);
        } else if (newStatus === StudentStatus.Alighted) {
            if (manualMode) {
                onUpdateStudent(student.id, newStatus);
                onScanned({ student, status: StudentStatus.Alighted });
            } else {
                proceedWithAlighting(student);
            }
        } else if (newStatus === StudentStatus.Absent) {
            onUpdateStudent(student.id, newStatus);
            showToast(`${student.name} marked as absent.`, 'info');
        } else {
             // Generic update (e.g. reversals)
             onUpdateStudent(student.id, newStatus);
             showToast(`${student.name} status updated to ${newStatus}.`, 'info');
        }
    };

    const handleToggleSelect = (studentId: string) => {
        setSelectedStudentIds(prev => prev.includes(studentId) ? prev.filter(id => id !== studentId) : [...prev, studentId]);
    };

    const handleBulkUpdate = (status: StudentStatus) => {
        selectedStudentIds.forEach(id => onUpdateStudent(id, status));
        setSelectedStudentIds([]);
    };

    const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.checked) {
            setSelectedStudentIds(studentsToShow.map(s => s.id));
        } else {
            setSelectedStudentIds([]);
        }
    };

    return (
        <div className="flex flex-col h-full">
            <Header title={`${trip.type} Trip`} />
            <div className="bg-white px-4 py-3 border-b border-gray-100">
                <div className="flex justify-between items-center text-sm text-gray-600 mb-2">
                    <div className="flex items-center gap-2">
                        <span className="font-bold text-[#303690]">{MOCK_DRIVER.assignedZone}</span>
                        <span className="text-gray-300">|</span>
                        <span className="text-xs">{trip.startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                    </div>
                    <GpsStatusIndicator status={gpsStatus} onClick={onGpsClick} />
                </div>

                {/* Route Information Section */}
                <div className="bg-blue-50/50 border border-blue-100/50 rounded-xl p-3 mb-3 flex items-center gap-3">
                    <div className="bg-white p-2 rounded-lg text-[#303690] shadow-sm">
                        <Icon name="map" className="w-5 h-5"/>
                    </div>
                    <div className="flex-grow">
                        <p className="text-[10px] font-bold text-gray-400 uppercase leading-none mb-1">Current Route</p>
                        <p className="font-bold text-gray-800 text-sm">{trip.route.name}</p>
                    </div>
                    <div className="text-right">
                         <p className="text-[10px] font-bold text-gray-400 uppercase leading-none mb-1">Zone</p>
                         <p className="font-bold text-gray-700 text-xs">{trip.route.zone}</p>
                    </div>
                </div>

                <div className="flex items-center justify-between">
                    <div className="text-xs font-bold text-gray-500 uppercase">Progress</div>
                    <div className="flex items-center gap-1">
                        <span className="font-bold text-2xl text-[#E70D8D]">{trip.students.filter(s => s.status === StudentStatus.Boarded).length}</span>
                        <span className="text-gray-400 text-sm">/ {trip.students.length}</span>
                    </div>
                </div>
                <div className="w-full bg-gray-100 rounded-full h-1.5 mt-1">
                    <div 
                        className="bg-[#E70D8D] h-1.5 rounded-full transition-all duration-500" 
                        style={{ width: `${(trip.students.filter(s => s.status === StudentStatus.Boarded).length / trip.students.length) * 100}%` }}
                    ></div>
                </div>
            </div>
            <div className="flex bg-white border-b border-gray-100">
                <button className={`flex-1 p-3 font-semibold text-sm transition-colors relative ${view === 'boarding' ? 'text-[#E70D8D]' : 'text-gray-500'}`} onClick={() => setView('boarding')}>
                    Boarding
                    {view === 'boarding' && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-[#E70D8D]"></div>}
                </button>
                <button className={`flex-1 p-3 font-semibold text-sm transition-colors relative ${view === 'alighting' ? 'text-[#E70D8D]' : 'text-gray-500'}`} onClick={() => setView('alighting')}>
                    Alighting
                    {view === 'alighting' && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-[#E70D8D]"></div>}
                </button>
            </div>
            <div className="p-4 bg-white border-b border-gray-50 sticky top-[230px] z-10">
                <div className="relative">
                    <Icon name="search" className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5"/>
                    <input type="text" placeholder="Search students..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-gray-50 rounded-xl p-3 pl-10 focus:outline-none focus:ring-2 focus:ring-pink-100 text-sm" />
                </div>
                <div className="flex items-center justify-between mt-3">
                    <div>
                        {manualMode && (
                            <div className="flex items-center gap-2">
                                <input 
                                    type="checkbox" 
                                    id="select-all" 
                                    ref={selectAllCheckboxRef}
                                    onChange={handleSelectAll}
                                    className="w-5 h-5 rounded text-[#E70D8D] border-gray-300 focus:ring-[#E70D8D]" 
                                />
                                <label htmlFor="select-all" className="text-xs font-bold uppercase text-gray-500 select-none">Select All</label>
                            </div>
                        )}
                    </div>
                    <div className="flex items-center gap-4">
                        <ModeToggle 
                            id="quick-scan-mode"
                            label="Quick Scan"
                            icon="zap"
                            checked={isQuickScanModeActive}
                            onChange={(checked) => {
                                setIsQuickScanModeActive(checked);
                                if(checked) setManualMode(false);
                            }}
                        />
                        <ModeToggle 
                            id="manual-mode"
                            label="Manual"
                            icon="userCheck"
                            checked={manualMode}
                            onChange={(checked) => {
                                setManualMode(checked);
                                if(checked) setIsQuickScanModeActive(false);
                            }}
                        />
                    </div>
                </div>
            </div>
            <div className="flex-grow overflow-y-auto pb-36 bg-white">
                {isQuickScanModeActive && <NfcScanningOverlay activeText="Quick Scan Active" />}
                {studentsToShow.length > 0 ? (
                    <ul>{studentsToShow.map(s => <StudentListItem key={s.id} student={s} onSelect={setActiveStudent} bulkMode={manualMode} isSelected={selectedStudentIds.includes(s.id)} onToggleSelect={handleToggleSelect} view={view} onUpdateStatus={handleStudentAction} isQuickScanMode={isQuickScanModeActive && (view === 'boarding' || view === 'alighting')}/>)}</ul>
                ) : (
                    <div className="text-center p-8 text-gray-400 mt-8">
                        <div className="bg-gray-50 rounded-full w-24 h-24 flex items-center justify-center mx-auto mb-4">
                             <Icon name={view === 'boarding' ? 'checkCircle' : 'bus'} className="w-10 h-10 text-gray-300"/>
                        </div>
                        <p className="font-semibold">{view === 'boarding' ? 'All students boarded!' : 'No students to alight.'}</p>
                    </div>
                )}
            </div>
            {manualMode && selectedStudentIds.length > 0 && (
                <div className="absolute bottom-24 left-4 right-4 bg-[#303690] text-white p-4 rounded-2xl shadow-xl flex justify-between items-center z-20">
                    <p className="font-bold">{selectedStudentIds.length} selected</p>
                    <div className="flex gap-2">
                         {view === 'boarding' && <>
                            <button onClick={() => handleBulkUpdate(StudentStatus.Boarded)} className="bg-[#E70D8D] text-white font-bold px-4 py-2 rounded-xl text-sm">Board</button>
                            <button onClick={() => handleBulkUpdate(StudentStatus.Absent)} className="bg-white/20 text-white font-bold px-4 py-2 rounded-xl text-sm">Absent</button>
                         </>}
                         {view === 'alighting' && <button onClick={() => handleBulkUpdate(StudentStatus.Alighted)} className="bg-[#E70D8D] text-white font-bold px-4 py-2 rounded-xl text-sm">Alight</button>}
                    </div>
                </div>
            )}
            <div className={`absolute bottom-0 left-0 right-0 bg-white p-4 border-t border-gray-100 shadow-2xl ${view === 'alighting' ? 'grid grid-cols-4 gap-4' : 'flex items-center'}`}>
                <button onClick={onReportIssue} className={`bg-yellow-100 text-yellow-700 font-bold p-3 rounded-xl flex flex-col items-center justify-center gap-1 h-14 transition-all duration-300 ${view === 'alighting' ? 'col-span-1' : 'w-full'}`}>
                    <Icon name="alertTriangle" className="w-5 h-5" />
                    <span className="text-[10px] uppercase">Report</span>
                </button>
                {view === 'alighting' && (
                    <button onClick={() => setIsEndConfirmationOpen(true)} disabled={isEndingTrip} className="bg-[#E70D8D] text-white font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 col-span-3 h-14 shadow-lg shadow-pink-200 animate-slide-up-button">
                        {isEndingTrip ? <Spinner className="text-white"/> : <><Icon name="logOut" className="w-5 h-5"/>End Trip</>}
                    </button>
                )}
            </div>
            {isScanning && <NfcScanningOverlay />}
             <BoardingConfirmationModal
                isOpen={!!studentToConfirm}
                onClose={() => setStudentToConfirm(null)}
                student={studentToConfirm}
                onConfirm={(student) => {
                    setStudentToConfirm(null);
                    proceedWithBoarding(student);
                }}
            />
             <StudentActionModal
                isOpen={!!activeStudent}
                onClose={() => setActiveStudent(null)}
                student={activeStudent}
                onUpdateStatus={handleStudentAction}
                onNotify={(name) => showToast(`Notifying ${name}'s guardian.`, 'info')}
                onCall={(name) => showToast(`Calling ${name}'s guardian.`, 'info')}
                mode="trip"
            />
            <Modal isOpen={isEndConfirmationOpen} onClose={() => setIsEndConfirmationOpen(false)} title="End Trip?">
                <div className="flex flex-col items-center pb-2 text-center">
                    <div className="w-20 h-20 bg-pink-50 rounded-full flex items-center justify-center mb-6">
                        <Icon name="logOut" className="w-8 h-8 text-[#E70D8D]" />
                    </div>
                    <h3 className="text-xl font-bold text-gray-900 mb-2">Are you sure you want to end this trip?</h3>
                    <p className="text-gray-500 text-sm mb-8 px-4">
                        Please ensure all students have alighted or have been accounted for before ending the trip.
                    </p>
                    <div className="grid grid-cols-2 gap-4 w-full">
                        <button onClick={() => setIsEndConfirmationOpen(false)} className="py-4 rounded-2xl bg-gray-50 text-gray-600 font-bold text-sm uppercase tracking-wide">
                            Cancel
                        </button>
                        <button onClick={handleEndTrip} className="py-4 rounded-2xl bg-[#E70D8D] text-white font-bold shadow-lg shadow-pink-200 text-sm uppercase tracking-wide">
                            Confirm
                        </button>
                    </div>
                </div>
            </Modal>
            <style>{`
                .toggle-checkbox:checked { right: 0; border-color: #E70D8D; } 
                .toggle-checkbox:checked + .toggle-label { background-color: #E70D8D; } 
                .toggle-label { transition: background-color 0.2s ease-in-out; }
                @keyframes slide-up-button {
                    from { transform: translateY(100%); opacity: 0; }
                    to { transform: translateY(0); opacity: 1; }
                }
                .animate-slide-up-button { animation: slide-up-button 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
            `}</style>
        </div>
    );
};

