    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Report Delay/Issue">
            <div className="flex flex-col gap-4">
                <div className="grid grid-cols-2 gap-3">{Object.values(IssueType).map(type => (<button key={type} onClick={() => setIssueType(type)} className={`p-3 rounded-xl border font-semibold text-sm ${issueType === type ? 'bg-[#303690] text-white border-[#303690] shadow-md' : 'bg-white text-gray-600 border-gray-200'}`}>{type}</button>))}</div>
