const StudentListSkeleton = () => <div className="p-4 space-y-4 animate-pulse"><div className="h-12 bg-gray-200 rounded-lg w-3/4 mb-6"></div>{Array.from({length: 5}).map((_, i) => <div className="flex gap-4" key={i}><div className="w-12 h-12 bg-gray-200 rounded-full"></div><div className="flex-grow space-y-2"><div className="h-4 bg-gray-200 rounded w-1/2"></div><div className="h-3 bg-gray-200 rounded w-1/3"></div></div></div>)}</div>;
const ProfileScreenSkeleton = () => <div className="p-6 space-y-6 animate-pulse flex flex-col items-center"><div className="w-32 h-32 bg-gray-200 rounded-full"></div><div className="w-1/2 h-6 bg-gray-200 rounded"></div><div className="w-full h-40 bg-gray-200 rounded-xl"></div></div>;
const HistoryScreenSkeleton = () => <div className="p-4 space-y-4 animate-pulse"><div className="flex gap-2 mb-4"><div className="flex-1 h-10 bg-gray-200 rounded-lg"></div><div className="flex-1 h-10 bg-gray-200 rounded-lg"></div></div>{Array.from({length: 4}).map((_,i) => <div key={i} className="h-20 bg-gray-200 rounded-xl"></div>)}</div>;
const TripSummarySkeleton = () => <div className="p-6 space-y-6 animate-pulse"><div className="h-32 bg-gray-200 rounded-2xl"></div><div className="grid grid-cols-2 gap-4"><div className="h-24 bg-gray-200 rounded-xl"></div><div className="h-24 bg-gray-200 rounded-xl"></div></div></div>;
const SettingsScreenSkeleton = () => <div className="p-6 space-y-6 animate-pulse"><div className="h-8 bg-gray-200 rounded w-1/4"></div><div className="h-32 bg-gray-200 rounded-xl"></div><div className="h-8 bg-gray-200 rounded w-1/4"></div><div className="h-32 bg-gray-200 rounded-xl"></div></div>;


export default App;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Screen, Student, Trip, TripType, StudentStatus, Issue, IssueType, Guardian, ToastType, TripHistoryItem, VerificationHistoryItem, GpsStatus, DataUsageItem, Coordinates, Route, ScheduledTrip } from './types';
import { MOCK_STUDENTS, GATE_MOCK_STUDENTS, MOCK_DRIVER, MOCK_GUARDIAN, MOCK_TRIP_HISTORY, MOCK_VERIFICATION_HISTORY, MOCK_DATA_USAGE_HISTORY, MOCK_ROUTES } from './constants';
import { Icon, IconName } from './components/Icon';
import { Modal } from './components/Modal';
import { Toast } from './components/Toast';
import { Spinner } from './components/Spinner';
import { Skeleton } from './components/Skeleton';

const APP_VERSION = '1.2.0';
const DEVICE_SIGNATURE = 'TG-DRV-8829-XPL';
const STORAGE_KEY_ACTIVE_TRIP = 'terra_go_active_trip_v1';

// Brand Colors
const BRAND_BLUE = '#303690';
const BRAND_PINK = '#E70D8D';

const SystemStatusBanner: React.FC<{ message: string; icon: IconName; className: string; }> = ({ message, icon, className }) => (
    <div className={`absolute top-8 left-0 right-0 z-[60] p-2 text-white text-xs font-bold text-center ${className} animate-fade-in`}>
