const DelayReportModal: React.FC<{ isOpen: boolean; onClose: () => void; onReport: (issue: Issue) => void; }> = ({ isOpen, onClose, onReport }) => {
    const [issueType, setIssueType] = useState<IssueType>(IssueType.Traffic);
    const [note, setNote] = useState('');
    const [isReporting, setIsReporting] = useState(false);

    const handleSubmit = () => { 
        setIsReporting(true);
        setTimeout(() => {
            onReport({ type: issueType, note, timestamp: new Date() }); 
            setNote('');
            setIsReporting(false);
        }, 1000);
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Report Delay/Issue">
            <div className="flex flex-col gap-4">
                <div className="grid grid-cols-2 gap-3">{Object.values(IssueType).map(type => (<button key={type} onClick={() => setIssueType(type)} className={`p-3 rounded-xl border font-semibold text-sm ${issueType === type ? 'bg-[#303690] text-white border-[#303690] shadow-md' : 'bg-white text-gray-600 border-gray-200'}`}>{type}</button>))}</div>
                <textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="Add an optional note..." className="w-full p-4 border border-gray-200 rounded-xl bg-gray-50 min-h-[100px] focus:outline-none focus:ring-2 focus:ring-[#303690]"/>
                <button onClick={handleSubmit} disabled={isReporting} className="w-full bg-[#303690] text-white font-bold p-4 rounded-xl h-14 flex items-center justify-center shadow-lg hover:opacity-90 transition-colors">
                    {isReporting ? <Spinner className="text-white"/> : 'Submit Report'}
                </button>
            </div>
        </Modal>
    );
};

