const OTAUpdateModal: React.FC<{ isOpen: boolean; onClose: () => void; onSuccess: () => void; }> = ({ isOpen, onClose, onSuccess }) => {
    const [step, setStep] = useState<'notice' | 'downloading' | 'complete'>('notice');
    const [progress, setProgress] = useState(0);

    const startUpdate = () => {
        setStep('downloading');
        const interval = setInterval(() => {
            setProgress(prev => {
                if (prev >= 100) {
                    clearInterval(interval);
                    setStep('complete');
                    return 100;
                }
                return prev + 2;
            });
        }, 50);
    };

    if (!isOpen) return null;

    return (
        <Modal isOpen={isOpen} onClose={step === 'downloading' ? () => {} : onClose} title="Software Update">
            <div className="flex flex-col items-center gap-6 py-2">
                {step === 'notice' && (
                    <>
                        <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center">
                            <Icon name="wifi" className="w-10 h-10 text-[#303690]" />
                        </div>
                        <div className="text-center">
                            <h3 className="text-xl font-bold text-[#303690]">New Update Available</h3>
                            <p className="text-sm text-gray-500 mt-2">Version 1.2.0 is ready to be installed.</p>
                        </div>
                        <div className="bg-gray-50 p-4 rounded-xl w-full">
                            <p className="text-xs font-bold text-gray-400 uppercase mb-2">Release Notes</p>
                            <ul className="text-sm text-gray-600 space-y-1 list-disc list-inside">
                                <li>Enhanced live GPS tracking accuracy</li>
                                <li>Reduced battery consumption during trips</li>
                                <li>New 'Quick Scan' attendance mode</li>
                                <li>UI performance improvements</li>
                            </ul>
                        </div>
                        <button 
                            onClick={startUpdate}
                            className="w-full bg-[#E70D8D] text-white font-bold py-4 rounded-xl shadow-lg"
                        >
                            Download & Install
                        </button>
                    </>
                )}

                {step === 'downloading' && (
                    <>
                        <div className="w-20 h-20 bg-pink-50 rounded-full flex items-center justify-center relative overflow-hidden">
                             <Spinner size={40} className="text-[#E70D8D]" />
                        </div>
                        <div className="text-center w-full">
                            <h3 className="text-xl font-bold text-[#303690]">{progress < 100 ? 'Downloading Update...' : 'Extracting Files...'}</h3>
                            <p className="text-sm text-gray-500 mt-1">Keep the app open during installation</p>
                        </div>
                        <div className="w-full space-y-2">
                            <div className="flex justify-between text-xs font-bold text-gray-400">
                                <span>Progress</span>
                                <span>{progress}%</span>
                            </div>
                            <div className="w-full bg-gray-100 rounded-full h-3 overflow-hidden">
                                <div 
                                    className="bg-[#E70D8D] h-full transition-all duration-300"
                                    style={{ width: `${progress}%` }}
                                />
                            </div>
                        </div>
                    </>
                )}

                {step === 'complete' && (
                    <>
                        <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center">
                            <Icon name="checkCircle" className="w-10 h-10 text-green-500" />
                        </div>
                        <div className="text-center">
                            <h3 className="text-xl font-bold text-gray-800">Update Ready!</h3>
                            <p className="text-sm text-gray-500 mt-2">Terra GO Driver Companion has been updated to version 1.2.0.</p>
                        </div>
                        <button 
                            onClick={onSuccess}
                            className="w-full bg-[#303690] text-white font-bold py-4 rounded-xl shadow-lg"
                        >
                            Finish & Reload
                        </button>
                    </>
                )}
            </div>
        </Modal>
    );
};

const StudentActionModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    student: Student | null; 
    onUpdateStatus: (student: Student, newStatus: StudentStatus) => void; 
    onNotify: (name: string) => void; 
    onCall: (name: string) => void; 
    mode: 'trip' | 'gate';
}> = ({ isOpen, onClose, student, onUpdateStatus, onNotify, onCall, mode }) => {
    if (!student) return null;

    const handleAction = (status: StudentStatus) => {
        onUpdateStatus(student, status);
        onClose();
    };

    const getActions = () => {
        switch(student.status) {
            case StudentStatus.NotBoarded: return <>
                <button onClick={() => handleAction(StudentStatus.Boarded)} className="w-full bg-[#303690] text-white font-bold p-4 rounded-xl shadow-lg">Board Student</button>
                <button onClick={() => handleAction(StudentStatus.Absent)} className="w-full bg-red-100 text-red-700 font-bold p-4 rounded-xl mt-2">Mark Absent</button>
            </>;
            case StudentStatus.Boarded: return <>
                <button onClick={() => handleAction(StudentStatus.Alighted)} className="w-full bg-[#E70D8D] text-white font-bold p-4 rounded-xl shadow-lg">Alight Student</button>
                <button onClick={() => handleAction(StudentStatus.NotBoarded)} className="w-full bg-orange-50 text-orange-700 font-bold p-4 rounded-xl border border-orange-100 mt-3 flex items-center justify-center gap-2">
                    <Icon name="xCircle" className="w-5 h-5" /> Undo Boarding
                </button>
            </>;
            case StudentStatus.Alighted: return <>
                <div className="text-center p-4 bg-green-50 rounded-xl mb-2 border border-green-100">
                    <p className="text-green-800 font-bold">Student has Alighted</p>
                </div>
                <button onClick={() => handleAction(StudentStatus.Boarded)} className="w-full bg-blue-50 text-blue-700 font-bold p-4 rounded-xl border border-blue-100 mt-2 flex items-center justify-center gap-2">
                    <Icon name="arrowRight" className="w-5 h-5 rotate-180" /> Undo Alighting (Back on Bus)
                </button>
            </>;
            case StudentStatus.NotArrived: return <>
                <button onClick={() => handleAction(StudentStatus.InSchool)} className="w-full bg-[#303690] text-white font-bold p-4 rounded-xl shadow-lg">Check In</button>
                <button onClick={() => handleAction(StudentStatus.Absent)} className="w-full bg-red-100 text-red-700 font-bold p-4 rounded-xl mt-2">Mark Absent</button>
            </>;
            case StudentStatus.InSchool: return <>
                <button onClick={() => handleAction(StudentStatus.LeftSchool)} className="w-full bg-[#E70D8D] text-white font-bold p-4 rounded-xl shadow-lg">Check Out</button>
                 <button onClick={() => handleAction(StudentStatus.NotArrived)} className="w-full bg-orange-50 text-orange-700 font-bold p-4 rounded-xl border border-orange-100 mt-3 flex items-center justify-center gap-2">
                    <Icon name="xCircle" className="w-5 h-5" /> Undo Check-in
                </button>
            </>;
            case StudentStatus.LeftSchool: return <>
                <div className="text-center p-4 bg-green-50 rounded-xl mb-2 border border-green-100">
                     <p className="text-green-800 font-bold">Student has Left School</p>
                </div>
                <button onClick={() => handleAction(StudentStatus.InSchool)} className="w-full bg-blue-50 text-blue-700 font-bold p-4 rounded-xl border border-blue-100 mt-2 flex items-center justify-center gap-2">
                    <Icon name="arrowRight" className="w-5 h-5 rotate-180" /> Undo Check-out
                </button>
            </>;
            case StudentStatus.Absent: return <>
                 <div className="text-center p-4 bg-red-50 rounded-xl mb-2 border border-red-100">
                     <p className="text-red-800 font-bold">Student marked Absent</p>
                </div>
                <button onClick={() => handleAction(mode === 'trip' ? StudentStatus.NotBoarded : StudentStatus.NotArrived)} className="w-full bg-orange-50 text-orange-700 font-bold p-4 rounded-xl border border-orange-100 mt-2 flex items-center justify-center gap-2">
                    <Icon name="xCircle" className="w-5 h-5" /> Reset Status
                </button>
            </>;
            default: return null;
        }
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Student Actions">
            <div className="flex flex-col items-center gap-4">
                <img src={student.imgUrl} alt={student.name} className="w-24 h-24 rounded-full border-4 border-gray-100 shadow-sm" />
                <h3 className="text-xl font-bold text-[#303690]">{student.name}</h3>
                <p className="text-gray-500 font-medium">{student.grade} &bull; ID: {student.admissionNumber}</p>
                <div className="my-2"><StatusBadge status={student.status} /></div>
                {student.alert && <StudentAlert alertText={student.alert} />}
                <div className="w-full space-y-3 pt-4 border-t border-gray-100">
                    {getActions()}
                    <button onClick={() => { onNotify(student.name); onClose(); }} className="w-full bg-gray-100 text-gray-700 font-bold p-4 rounded-xl hover:bg-gray-200">Notify Parent of Arrival</button>
                    <button onClick={() => { onCall(student.name); onClose(); }} className="w-full bg-gray-100 text-gray-700 font-bold p-4 rounded-xl hover:bg-gray-200">Call Parent/Guardian</button>
                </div>
            </div>
        </Modal>
    );
};

const GuardianOtpModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    onSuccess: (guardianName: string, studentName: string) => void;
}> = ({ isOpen, onClose, onSuccess }) => {
    const [view, setView] = useState<'enterCode' | 'showDetails'>('enterCode');
    const [otp, setOtp] = useState('');
    const [error, setError] = useState('');
    const [verificationData, setVerificationData] = useState<{guardian: Guardian, student: Student} | null>(null);
    const [isVerifying, setIsVerifying] = useState(false);

    const handleVerifyCode = () => {
        setError('');
        setIsVerifying(true);
        setTimeout(() => {
            if (otp === '1234') {
                const guardian = MOCK_GUARDIAN;
                const student = MOCK_STUDENTS.find(s => s.id === guardian.authorizedStudentId);
                if (guardian && student) {
                    setVerificationData({ guardian, student });
                    setView('showDetails');
                } else {
                    setError('Could not find matching guardian/student.');
                }
            } else {
                setError('Invalid or expired code. Please try again.');
            }
            setIsVerifying(false);
        }, 1500);
    };

    const handleConfirmRelease = () => {
        if (verificationData) {
            onSuccess(verificationData.guardian.name, verificationData.student.name);
        }
        setOtp('');
        setError('');
        setVerificationData(null);
        setView('enterCode');
    };

    useEffect(() => {
        if (!isOpen) {
            setTimeout(() => {
              setOtp('');
              setError('');
              setVerificationData(null);
              setView('enterCode');
            }, 300);
        }
    }, [isOpen]);

    const renderEnterCode = () => (
        <div className="flex flex-col items-center gap-4">
            <p className="text-gray-600 text-center mb-4">Enter the 4-digit code from the guardian's app to view pickup details.</p>
            <input type="tel" maxLength={4} value={otp} onChange={e => setOtp(e.target.value.replace(/[^0-9]/g, ''))} className="w-48 p-4 text-2xl tracking-[1em] text-center border-2 rounded-xl bg-gray-50 focus:outline-none focus:ring-2 focus:ring-[#E70D8D] font-mono text-[#303690]" placeholder="----"/>
            {error && <p className="text-red-500 text-sm text-center -mt-2">{error}</p>}
            <button onClick={handleVerifyCode} disabled={otp.length !== 4 || isVerifying} className="w-full bg-[#E70D8D] text-white font-bold p-4 rounded-xl disabled:bg-gray-300 h-14 flex items-center justify-center shadow-lg">
                {isVerifying ? <Spinner className="text-white"/> : 'Verify Code'}
            </button>
        </div>
    );

    const renderShowDetails = () => {
        if (!verificationData) return null;
        const { guardian, student } = verificationData;
        return (
            <div className="flex flex-col items-center gap-4">
                <p className="text-gray-600 text-center mb-4 font-semibold">Please verify the guardian and student details before release.</p>
                <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 w-full space-y-4">
                    <div className="flex items-center gap-4">
                        <img src={guardian.imgUrl} className="w-16 h-16 rounded-full border-2 border-blue-500" alt={guardian.name} />
                        <div>
                            <p className="font-bold text-[#303690]">{guardian.name} <span className="text-sm font-normal text-gray-500">({guardian.relationship})</span></p>
                            <p className="text-sm text-gray-600">Phone: {guardian.phone}</p>
                            <p className="text-sm text-gray-600">ID: {guardian.idNumber}</p>
                        </div>
                    </div>
                     <hr className="border-gray-200"/>
                     <div className="flex items-center gap-4">
                        <img src={student.imgUrl} className="w-16 h-16 rounded-full border-2 border-green-500" alt={student.name} />
                        <div>
                            <p className="font-bold text-[#303690]">{student.name}</p>
                            <p className="text-sm text-gray-600">Grade: {student.grade}</p>
                            <p className="text-sm text-gray-600">ID: {student.admissionNumber}</p>
                        </div>
                    </div>
                </div>
                <button onClick={handleConfirmRelease} className="w-full bg-green-600 text-white font-bold p-4 rounded-xl shadow-lg hover:bg-green-700">Confirm Release & Scan Next</button>
            </div>
        );
    }

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Guardian Verification">
            {view === 'enterCode' ? renderEnterCode() : renderShowDetails()}
        </Modal>
    );
};

