                <button onClick={onReset} className="flex-1 bg-red-50 text-red-600 font-bold p-3 rounded-xl hover:bg-red-100 text-sm">Reset Statistics</button>
                <button onClick={onClose} className="flex-1 bg-gray-100 text-gray-600 font-bold p-3 rounded-xl hover:bg-gray-200 text-sm">Close</button>
            </div>
        </div>
    </Modal>
);

const MapModal: React.FC<{ isOpen: boolean; onClose: () => void; location: Coordinates | null; }> = ({ isOpen, onClose, location }) => (
    <Modal isOpen={isOpen} onClose={onClose} title="Current Location">
        <div className="relative w-full h-64 bg-gray-200 rounded-xl overflow-hidden flex items-center justify-center">
             {/* Placeholder Map UI */}
             <div className="absolute inset-0 opacity-30 bg-[url('https://www.transparenttextures.com/patterns/skulls.png')]"></div>
             <div className="absolute inset-0 grid grid-cols-6 grid-rows-4 gap-0.5 opacity-10 pointer-events-none">
                 {Array.from({length: 24}).map((_, i) => <div key={i} className="border border-gray-400"></div>)}
