                    <div className={`flex items-center gap-1 font-bold text-[11px] px-2 py-0.5 rounded-full ${isActive ? 'bg-blue-50 text-[#303690]' : 'bg-gray-50 text-gray-400'}`}>
                        <Icon name="clock" className="w-3 h-3" />
                        {statusText}
                    </div>
                    {isActive && <span className="text-[10px] font-bold text-[#E70D8D] uppercase tracking-tighter">Ready</span>}
