const StudentListItem: React.FC<{
    student: Student;
    onSelect: (student: Student) => void;
    bulkMode: boolean;
    isSelected: boolean;
    onToggleSelect: (studentId: string) => void;
    view: 'boarding' | 'alighting' | 'checkin' | 'checkout';
    onUpdateStatus: (student: Student, newStatus: StudentStatus) => void;
    isQuickScanMode?: boolean;
}> = ({ student, onSelect, bulkMode, isSelected, onToggleSelect, view, onUpdateStatus, isQuickScanMode }) => {
    const isQuickScanTarget = 
        (view === 'boarding' && student.status === StudentStatus.NotBoarded) ||
        (view === 'alighting' && student.status === StudentStatus.Boarded) ||
        (view === 'checkin' && student.status === StudentStatus.NotArrived) ||
        (view === 'checkout' && student.status === StudentStatus.InSchool);

    const getQuickScanStatus = () => {
        if (view === 'boarding') return StudentStatus.Boarded;
        if (view === 'alighting') return StudentStatus.Alighted;
        if (view === 'checkin') return StudentStatus.InSchool;
        if (view === 'checkout') return StudentStatus.LeftSchool;
        return StudentStatus.Boarded;
    };

    return (
        <li 
            className={`bg-white p-4 border-b border-gray-50 flex items-start gap-4 transition-colors ${isQuickScanMode && isQuickScanTarget ? 'cursor-pointer hover:bg-blue-50' : ''}`}
            onClick={isQuickScanMode && isQuickScanTarget ? () => onUpdateStatus(student, getQuickScanStatus()) : () => onSelect(student)}
        >
            {bulkMode ? (
                <div onClick={e => e.stopPropagation()} className="flex items-center h-full pt-3">
                    <input type="checkbox" checked={isSelected} onChange={() => onToggleSelect(student.id)} className="w-6 h-6 rounded text-[#E70D8D] border-gray-300 focus:ring-[#E70D8D]" />
                </div>
            ) : (
                <div className="relative">
                    <img src={student.imgUrl} alt={student.name} className="w-12 h-12 rounded-full object-cover border border-gray-100"/>
                    {student.status === StudentStatus.Boarded && <div className="absolute -bottom-1 -right-1 bg-green-500 rounded-full p-0.5 border-2 border-white"><Icon name="checkCircle" className="w-3 h-3 text-white"/></div>}
                </div>
            )}
            <div className="flex-grow cursor-pointer" onClick={() => onSelect(student)}>
                <p className="font-bold text-gray-800 text-base">{student.name}</p>
                <p className="text-xs text-gray-500 font-medium">ID: {student.admissionNumber} &bull; {student.grade}</p>
                <div className="mt-2"><StatusBadge status={student.status} /></div>
                {student.alert && <StudentAlert alertText={student.alert} />}
            </div>
            {!bulkMode && !isQuickScanMode && (
                <div className="flex flex-col gap-2 flex-shrink-0">
                    {view === 'boarding' && student.status === StudentStatus.NotBoarded && (
                        <>
                            <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.Boarded); }} className="px-3 py-1.5 text-xs bg-[#303690] text-white rounded-lg font-bold hover:opacity-90 transition-colors shadow-sm">Board</button>
                            <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.Absent); }} className="px-3 py-1.5 text-xs bg-red-100 text-red-700 rounded-lg font-bold hover:bg-red-200 transition-colors">Absent</button>
                        </>
                    )}
                    {view === 'alighting' && student.status === StudentStatus.Boarded && (
                        <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.Alighted); }} className="px-3 py-1.5 text-xs bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 transition-colors shadow-sm">Alight</button>
                    )}
                    {view === 'checkin' && student.status === StudentStatus.NotArrived && (
                        <>
                            <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.InSchool); }} className="px-3 py-1.5 text-xs bg-[#303690] text-white rounded-lg font-bold hover:opacity-90 transition-colors shadow-sm">Check In</button>
                            <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.Absent); }} className="px-3 py-1.5 text-xs bg-red-100 text-red-700 rounded-lg font-bold hover:bg-red-200 transition-colors">Absent</button>
                        </>
                    )}
                    {view === 'checkout' && student.status === StudentStatus.InSchool && (
                        <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(student, StudentStatus.LeftSchool); }} className="px-3 py-1.5 text-xs bg-[#303690] text-white rounded-lg font-bold hover:opacity-90 transition-colors shadow-sm">Check Out</button>
                    )}
                </div>
            )}
        </li>
    );
};

