                    <div>
                        {manualMode && (
                            <div className="flex items-center gap-2">
                                <input 
                                    type="checkbox" 
                                    id="select-all-gate" 
                                    ref={selectAllCheckboxRef}
                                    onChange={handleSelectAll}
