                            }}
                        />
                        <ModeToggle 
                            id="gate-manual-mode"
                            label="Manual"
                            icon="userCheck"
                            checked={manualMode}
                            onChange={(checked) => {
                                setManualMode(checked);
                                if(checked) setIsQuickScanModeActive(false);
                            }}
                        />
                    </div>
                </div>
            </div>
