                        <Icon name="logOut" className="w-8 h-8 text-[#E70D8D]" />
                    </div>
                    <h3 className="text-xl font-bold text-gray-900 mb-2">Are you sure you want to end this trip?</h3>
                    <p className="text-gray-500 text-sm mb-8 px-4">
                        Please ensure all students have alighted or have been accounted for before ending the trip.
                    </p>
                    <div className="grid grid-cols-2 gap-4 w-full">
                        <button onClick={() => setIsEndConfirmationOpen(false)} className="py-4 rounded-2xl bg-gray-50 text-gray-600 font-bold text-sm uppercase tracking-wide">
                            Cancel
                        </button>
                        <button onClick={handleEndTrip} className="py-4 rounded-2xl bg-[#E70D8D] text-white font-bold shadow-lg shadow-pink-200 text-sm uppercase tracking-wide">
                            Confirm
