    const alightedCount = trip.students.filter(s => s.status === StudentStatus.Alighted).length;
    const absentCount = trip.students.filter(s => s.status === StudentStatus.Absent).length;
    const duration = trip.endTime ? Math.round((trip.endTime.getTime() - trip.startTime.getTime()) / 60000) : 0;

    const handleSubmit = () => {
        setIsSubmitting(true);
        setTimeout(() => {
            onDone();
        }, 1500);
    };

    return (
        <div className="flex flex-col h-full bg-gray-50">
            <Header title="Trip Summary"/>
            <div className="flex-grow p-6 overflow-y-auto">
                <div className="bg-[#E70D8D] rounded-2xl shadow-lg p-6 mb-6 text-center text-white relative overflow-hidden">
                     <div className="absolute -top-10 -right-10 w-32 h-32 bg-white rounded-full blur-2xl opacity-20"></div>
                     <div className="relative z-10">
                        <h2 className="text-2xl font-bold mb-1">{trip.type} Trip Completed</h2>
                        <p className="text-pink-100">{trip.route.name}</p>
                     </div>
                </div>
                <div className="grid grid-cols-2 gap-4 mb-6">
                    <SummaryCard icon="clock" label="Duration" value={`${duration} min`} />
                    <SummaryCard icon="users" label="Boarded" value={`${boardedCount}`} />
                    <SummaryCard icon="logOut" label="Alighted" value={`${alightedCount}`} />
                    <SummaryCard icon="xCircle" label="Absent" value={`${absentCount}`} />
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase text-gray-500 mb-3 tracking-wider">Issues Reported ({trip.issues.length})</h3>
                    {trip.issues.length > 0 ? (
                        <ul className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 space-y-3">{trip.issues.map((issue, index) => (<li key={index} className="border-b border-gray-100 last:border-b-0 pb-2 last:pb-0"><p className="font-semibold text-gray-800">{issue.type}</p><p className="text-sm text-gray-600">{issue.note}</p></li>))}</ul>
                    ) : (
                        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 text-center text-gray-400">No issues reported.</div>
                    )}
                </div>
            </div>
            <div className="p-4 bg-white border-t border-gray-100 space-y-3">
                 <button onClick={onBack} className="w-full bg-gray-100 text-gray-600 font-bold py-4 rounded-xl">Go Back</button>
                 <button onClick={handleSubmit} disabled={isSubmitting} className="w-full bg-[#E70D8D] text-white font-bold py-4 rounded-xl shadow-lg hover:opacity-90 transition-colors h-14 flex items-center justify-center">
                    {isSubmitting ? <Spinner className="text-white"/> : 'Submit Report'}
                 </button>
            </div>
