                                </div>
                                <div className="flex-grow">
                                    <p className="font-bold text-gray-800 text-sm">{v.studentName}</p>
                                    <p className="text-xs text-gray-500">Released to: <span className="font-medium text-gray-700">{v.guardianName}</span></p>
                                </div>
                                <p className="text-xs text-gray-400">{formatDate(v.timestamp)}</p>
                            </div>
                        )) : <EmptyState message="No verifications found." />}
                    </div>
                )}
            </div>
        </div>
    );
};

