const GateAttendanceScreen: React.FC<{ onBack: () => void; onGuardianVerify: () => void; showToast: (msg: string, type?: ToastType) => void; onScanned: (data: {student: Student, status: StudentStatus} | null) => void; }> = ({ onBack, onGuardianVerify, showToast, onScanned }) => {
    const [students, setStudents] = useState<Student[]>(GATE_MOCK_STUDENTS);
    const [searchTerm, setSearchTerm] = useState('');
    const [view, setView] = useState<'checkin' | 'checkout'>('checkin');
    const [manualMode, setManualMode] = useState(false);
    const [isQuickScanModeActive, setIsQuickScanModeActive] = useState(false);
    const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);
    const [isScanning, setIsScanning] = useState(false); 
    const [activeStudent, setActiveStudent] = useState<Student | null>(null);
    const [studentToConfirm, setStudentToConfirm] = useState<Student | null>(null);
    const selectAllCheckboxRef = useRef<HTMLInputElement>(null);
    const scanIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

    const studentsToShow = useMemo(() => {
        let list = students;
        if (view === 'checkin') {
            list = students.filter(s => s.status === StudentStatus.NotArrived || s.status === StudentStatus.Absent);
        } else {
            list = students.filter(s => s.status === StudentStatus.InSchool);
        }
        if (!searchTerm) return list;
        return list.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.admissionNumber.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [students, view, searchTerm]);

    useEffect(() => {
        setSelectedStudentIds([]);
    }, [manualMode, view]);

    useEffect(() => {
        setIsQuickScanModeActive(false);
    }, [view]);

    useEffect(() => {
        if (selectAllCheckboxRef.current) {
            const allVisibleSelected = studentsToShow.length > 0 && selectedStudentIds.length === studentsToShow.length;
            const someSelected = selectedStudentIds.length > 0 && selectedStudentIds.length < studentsToShow.length;
            selectAllCheckboxRef.current.checked = allVisibleSelected;
            selectAllCheckboxRef.current.indeterminate = someSelected;
        }
    }, [selectedStudentIds, studentsToShow]);

    useEffect(() => {
        const stopScanning = () => {
            if (scanIntervalRef.current) {
                clearInterval(scanIntervalRef.current);
                scanIntervalRef.current = null;
            }
        };

        if (isQuickScanModeActive) {
            scanIntervalRef.current = setInterval(() => {
                setStudents(currentStudents => {
                    const targetStatus = view === 'checkin' ? StudentStatus.NotArrived : StudentStatus.InSchool;
                    const nextStatus = view === 'checkin' ? StudentStatus.InSchool : StudentStatus.LeftSchool;

                    const studentToProcess = currentStudents.find(s => s.status === targetStatus);

                    if (studentToProcess) {
                        onScanned({ student: studentToProcess, status: nextStatus });
                        return currentStudents.map(s => s.id === studentToProcess.id ? { ...s, status: nextStatus, lastUpdateTime: new Date() } : s);
                    } else {
                        stopScanning();
                        setIsQuickScanModeActive(false);
                        showToast(`All students ${view === 'checkin' ? 'checked in' : 'checked out'} via Quick Scan.`, 'info');
                        return currentStudents;
                    }
                });
            }, 2000);
        }

        return () => stopScanning();
    }, [isQuickScanModeActive, view, showToast, onScanned]);

    const performUpdate = (student: Student, newStatus: StudentStatus) => {
        setStudents(prev => prev.map(s => s.id === student.id ? { ...s, status: newStatus, lastUpdateTime: new Date() } : s));
        onScanned({ student, status: newStatus });
    };

    const proceedWithScan = (student: Student, newStatus: StudentStatus) => {
        setIsScanning(true);
        setTimeout(() => {
            setIsScanning(false);
            performUpdate(student, newStatus);
        }, 1200);
    };

    const handleStudentAction = (student: Student, newStatus: StudentStatus) => {
        if (newStatus === StudentStatus.InSchool && view === 'checkin') {
            if (student.alert) {
                setStudentToConfirm(student);
                return;
            }
            if (manualMode || isQuickScanModeActive) {
                performUpdate(student, newStatus);
            } else {
                proceedWithScan(student, newStatus);
            }
        } else if (newStatus === StudentStatus.LeftSchool && view === 'checkout') {
             if (manualMode || isQuickScanModeActive) {
                performUpdate(student, newStatus);
            } else {
                proceedWithScan(student, newStatus);
            }
        } else {
            performUpdate(student, newStatus);
        }
    };

    const handleToggleSelect = (studentId: string) => {
        setSelectedStudentIds(prev => prev.includes(studentId) ? prev.filter(id => id !== studentId) : [...prev, studentId]);
    };

    const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.checked) {
            setSelectedStudentIds(studentsToShow.map(s => s.id));
        } else {
            setSelectedStudentIds([]);
        }
    };

    const handleBulkUpdate = (status: StudentStatus) => {
        setStudents(prev => prev.map(s => selectedStudentIds.includes(s.id) ? { ...s, status, lastUpdateTime: new Date() } : s));
        setSelectedStudentIds([]);
        showToast(`${selectedStudentIds.length} students updated.`, 'info');
    };

    return (
        <div className="flex flex-col h-full bg-gray-50">
            <Header title="Gate Attendance" onBack={onBack}/>
             <div className="bg-white px-4 py-3 border-b border-gray-100">
                <div className="flex justify-between items-center text-sm text-gray-600">
                    <div className="flex flex-col">
                        <span className="text-xs font-bold text-gray-400 uppercase">In School</span>
                        <span className="font-bold text-xl text-[#303690]">{students.filter(s => s.status === StudentStatus.InSchool).length}</span>
                    </div>
                    <div className="flex flex-col items-end">
                        <span className="text-xs font-bold text-gray-400 uppercase">Departed</span>
                        <span className="font-bold text-xl text-gray-600">{students.filter(s => s.status === StudentStatus.LeftSchool).length}</span>
                    </div>
                </div>
            </div>
             <div className="flex bg-white border-b border-gray-100">
                <button className={`flex-1 p-3 font-semibold text-sm transition-colors relative ${view === 'checkin' ? 'text-[#E70D8D]' : 'text-gray-500'}`} onClick={() => setView('checkin')}>
                    Arrivals
                    {view === 'checkin' && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-[#E70D8D]"></div>}
                </button>
                <button className={`flex-1 p-3 font-semibold text-sm transition-colors relative ${view === 'checkout' ? 'text-[#E70D8D]' : 'text-gray-500'}`} onClick={() => setView('checkout')}>
                    Departures
                    {view === 'checkout' && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-[#E70D8D]"></div>}
                </button>
            </div>
            <div className="p-4 bg-white border-b border-gray-50 sticky top-[165px] z-10">
                <div className="flex justify-center items-center gap-3 mb-4">
                     <ModeToggle 
                        id="gate-quick-scan-mode"
                        label="Quick Scan"
                        icon="zap"
                        checked={isQuickScanModeActive}
                        onChange={(checked) => {
                            setIsQuickScanModeActive(checked);
                            if(checked) setManualMode(false);
                        }}
                    />
                    <ModeToggle 
                        id="gate-manual-mode"
                        label="Manual Mode"
                        icon="userCheck"
                        checked={manualMode}
                        onChange={(checked) => {
                            setManualMode(checked);
                            if(checked) setIsQuickScanModeActive(false);
                        }}
                    />
                </div>
                <div className="relative"><Icon name="search" className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5"/><input type="text" placeholder="Search student..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-gray-50 rounded-xl p-3 pl-10 focus:outline-none focus:ring-2 focus:ring-blue-100 text-sm"/></div>
                {manualMode && (
                    <div className="flex items-center gap-2 mt-3 pl-1">
                        <input 
                            type="checkbox" 
                            id="select-all-gate" 
                            ref={selectAllCheckboxRef}
                            onChange={handleSelectAll}
                            className="w-5 h-5 rounded text-[#E70D8D] border-gray-300 focus:ring-[#E70D8D]" 
                        />
                        <label htmlFor="select-all-gate" className="text-xs font-bold uppercase text-gray-500 select-none">Select All Students</label>
                    </div>
                )}
            </div>
            <div className="flex-grow overflow-y-auto pb-24 bg-white">
                {isQuickScanModeActive && <NfcScanningOverlay activeText="Quick Scan Active" />}
                {studentsToShow.length > 0 ? (
                    <ul>{studentsToShow.map(student => (
                       <StudentListItem 
                            key={student.id} 
                            student={student} 
                            onSelect={setActiveStudent} 
                            bulkMode={manualMode} 
                            isSelected={selectedStudentIds.includes(student.id)} 
                            onToggleSelect={handleToggleSelect} 
                            view={view} 
                            onUpdateStatus={handleStudentAction} 
                            isQuickScanMode={isQuickScanModeActive}
                        />
                    ))}</ul>
                ) : (
                    <div className="text-center p-8 text-gray-400 mt-8">
                         <div className="bg-gray-50 rounded-full w-24 h-24 flex items-center justify-center mx-auto mb-4">
                            <Icon name={view === 'checkin' ? 'logIn' : 'logOut'} className="w-10 h-10 text-gray-300"/>
                        </div>
                        <p className="font-semibold">{view === 'checkin' ? 'No arrivals pending.' : 'No departures pending.'}</p>
                    </div>
                )}
            </div>

            {manualMode && selectedStudentIds.length > 0 ? (
                 <div className="absolute bottom-4 left-4 right-4 bg-[#303690] text-white p-4 rounded-2xl shadow-xl flex justify-between items-center z-20">
                    <p className="font-bold">{selectedStudentIds.length} selected</p>
                    <div className="flex gap-2">
                         {view === 'checkin' && <>
                            <button onClick={() => handleBulkUpdate(StudentStatus.InSchool)} className="bg-[#E70D8D] text-white font-bold px-4 py-2 rounded-xl text-sm">Check In</button>
                            <button onClick={() => handleBulkUpdate(StudentStatus.Absent)} className="bg-white/20 text-white font-bold px-4 py-2 rounded-xl text-sm">Absent</button>
                         </>}
                         {view === 'checkout' && <button onClick={() => handleBulkUpdate(StudentStatus.LeftSchool)} className="bg-[#E70D8D] text-white font-bold px-4 py-2 rounded-xl text-sm">Check Out</button>}
                    </div>
                </div>
            ) : (
                !manualMode && (
                    <div className="bg-white p-4 border-t border-gray-100 shadow-2xl"><button onClick={onGuardianVerify} className="w-full bg-[#E70D8D] text-white font-bold py-3.5 px-4 rounded-xl flex items-center justify-center gap-2 hover:opacity-90 transition-colors shadow-lg"><Icon name="shield" className="w-5 h-5"/>Guardian Verification for Pickup</button></div>
                )
            )}

            {isScanning && <NfcScanningOverlay />}
            <BoardingConfirmationModal
                isOpen={!!studentToConfirm}
                onClose={() => setStudentToConfirm(null)}
                student={studentToConfirm}
                onConfirm={(confirmedStudent) => {
                    setStudentToConfirm(null);
                    if (manualMode || isQuickScanModeActive) {
                         performUpdate(confirmedStudent, StudentStatus.InSchool);
                    } else {
                        proceedWithScan(confirmedStudent, StudentStatus.InSchool);
                    }
                }}
                title="Check-in Confirmation"
                confirmText="Confirm Check-in"
            />
             <StudentActionModal
                isOpen={!!activeStudent}
                onClose={() => setActiveStudent(null)}
                student={activeStudent}
                onUpdateStatus={handleStudentAction}
                onNotify={(name) => showToast(`Notifying ${name}'s guardian.`, 'info')}
                onCall={(name) => showToast(`Calling ${name}'s guardian.`, 'info')}
                mode="gate"
            />
             <style>{`.toggle-checkbox:checked { right: 0; border-color: #E70D8D; } .toggle-checkbox:checked + .toggle-label { background-color: #E70D8D; } .toggle-label { transition: background-color 0.2s ease-in-out; }`}</style>
        </div>
    );
};

