    };
    return <span className={`px-3 py-1 text-xs font-semibold rounded-full ${statusStyles[status]}`}>{status}</span>;
};

const EmptyState: React.FC<{ message: string; icon?: IconName }> = ({ message, icon = 'fileText' }) => (
    <div className="flex flex-col items-center justify-center text-center p-8 text-gray-400 mt-8">
